const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for fillConnectedPixels(image, row, col, startingColor, newColor, visited):
//     when this call returns, the pixel at (`row`, `col`) and every
//     pixel connected to it that had `startingColor` is repainted to
//     `newColor` and is in the visited set.
const fillConnectedPixels = (image, row, col, startingColor, newColor, visited) => {
    // Base cases
    if (!isInBounds(image, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    // Only pixels that originally matched the starting pixel's color
    // are part of the fill region.
    if (image[row][col] !== startingColor) return;

    // Process node
    visited.add(curPositionString);
    image[row][col] = newColor;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor pixel and
        // everything connected to it that had `startingColor` is
        // repainted and in the visited set. Trust it, do not trace it.
        // This function already repainted (`row`, `col`) and put it into
        // visited, and each neighbor's contract covers the rest —
        // together, that is this function's full contract, kept.
        fillConnectedPixels(image, newRow, newCol, startingColor, newColor, visited);
    }
};

const floodFill = (image, sr, sc, color) => {
    const startingColor = image[sr][sc];

    // If the new color equals the starting color, the fill changes nothing.
    // Returning early also guards against re-visiting already-painted pixels.
    if (startingColor === color) return image;

    const visited = new Set();
    // The recursive leap of faith: trust the contract. When this
    // call returns, the starting pixel and every pixel connected to it
    // that had `startingColor` is repainted to the new color. We do not
    // trace inside; we just return the finished image.
    fillConnectedPixels(image, sr, sc, startingColor, color, visited);

    return image;
};

const LAND = 1;

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for getIslandArea(grid, row, col, visited):
//     when this call returns, every land cell of the island
//     containing (`row`, `col`) is in the visited set, and the
//     returned value is the number of cells in that island. Water,
//     out-of-bounds, and already-visited cells return 0.
const getIslandArea = (grid, row, col, visited) => {
    // Base cases
    if (!isInBounds(grid, row, col)) return 0;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return 0;

    if (grid[row][col] !== LAND) return 0;

    // Process node
    visited.add(curPositionString);

    // This cell contributes 1 to the island's area.
    let islandArea = 1;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor's side of
        // the island is counted and its cells are in the visited set.
        // Trust it, do not trace it. This cell's own 1 plus each
        // neighbor's guaranteed count add up to exactly this function's
        // contract: the whole island, counted once.
        islandArea += getIslandArea(grid, newRow, newCol, visited);
    }

    return islandArea;
};

const maxAreaOfIsland = (grid) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    let maxIslandArea = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = grid[row][col];
            if (terrainType !== LAND) continue;

            // The recursive leap of faith: trust the contract. When this
            // call returns, islandArea is the full size of this island and
            // all of its cells are in the visited set, so the loop can never
            // count this island again. We do not trace inside; we just
            // compare it to the running maximum and move on.
            const islandArea = getIslandArea(grid, row, col, visited);
            maxIslandArea = Math.max(maxIslandArea, islandArea);
        }
    }

    return maxIslandArea;
};

const buildEmployeeMap = (employees) => {
    const employeeMap = {};

    for (const employee of employees) {
        employeeMap[employee.id] = employee;
    }

    return employeeMap;
};

// CONTRACT for getTotalImportance(employeeMap, employeeId, visited):
//     when this call returns, the returned value is the importance
//     of employee `employeeId` plus the importance of every employee
//     below them (subordinates, their subordinates, and so on), and
//     all of those ids are in the visited set.
//     An id that is not in the map, or already in the visited set,
//     returns 0.
const getTotalImportance = (employeeMap, employeeId, visited) => {
    // Base cases
    const employeeInMap = employeeMap.hasOwnProperty(employeeId);
    if (!employeeInMap) return 0;

    if (visited.has(employeeId)) return 0;

    // Process node
    visited.add(employeeId);

    const employee = employeeMap[employeeId];
    let totalImportance = employee.importance;

    // Recurse on neighbors
    // Each subordinate id is a "neighbor" of this employee in the
    // reporting tree, so we add up their whole subtrees too.
    for (const subordinateId of employee.subordinates) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, its value is the
        // subordinate's importance plus everyone below them, and their
        // ids are in the visited set. Trust it, do not trace it. This
        // employee's own importance plus each subordinate's guaranteed
        // total is exactly this function's contract, kept.
        totalImportance += getTotalImportance(employeeMap, subordinateId, visited);
    }

    return totalImportance;
};

const getImportance = (employees, id) => {
    const employeeMap = buildEmployeeMap(employees);

    // The hierarchy is a tree, but tracking visited ids keeps us safe
    // even if the data accidentally contained a cycle.
    const visited = new Set();

    // The recursive leap of faith: trust the contract. When this
    // call returns, its value is the importance of employee `id` plus
    // the importance of everyone below them in the hierarchy. We do
    // not trace inside; we just return that total.
    return getTotalImportance(employeeMap, id, visited);
};

const LAND = 1;

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
