// Returns true if every cell of this grid2 island also sits on land in grid1.
// CONTRACT for exploreIsland(grid1, grid2, row, col, visited):
//     when this call returns, every cell of the grid2 island
//     containing (`row`, `col`) is in the visited set, and the
//     returned value is true only when every one of those cells
//     also sits on land in grid1. Water, out-of-bounds, and
//     already-visited cells return true because they break no rule.
const exploreIsland = (grid1, grid2, row, col, visited) => {
    // Base cases
    if (!isInBounds(grid2, row, col)) return true;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return true;

    if (grid2[row][col] !== LAND) return true;

    // Process node
    visited.add(curPositionString);

    // The two grids are the same size, so we can check grid1 directly.
    let islandIsSubIsland = grid1[row][col] === LAND;

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor's side of
        // the island is in the visited set, and its answer says whether
        // that side passes the land-in-grid1 test. Trust it, do not
        // trace it. This cell's own check plus each neighbor's
        // guaranteed answer combine into exactly this function's
        // contract, kept.
        // Recurse BEFORE checking the flag so the whole island still gets
        // marked as visited, even after we know it fails the sub-island test.
        const neighborSideIsSubIsland = exploreIsland(grid1, grid2, newRow, newCol, visited);

        if (!neighborSideIsSubIsland) islandIsSubIsland = false;
    }

    return islandIsSubIsland;
};

const countSubIslands = (grid1, grid2) => {
    const numRows = grid2.length;
    const numCols = grid2[0].length;

    let numSubIslands = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = grid2[row][col];
            if (terrainType !== LAND) continue;

            // The recursive leap of faith: trust the contract. When this
            // call returns, the whole island is in the visited set — so the
            // loop never sees it again — and the answer tells us whether
            // every cell of it sits on land in grid1. We do not trace
            // inside; we just count the island if it passed.
            const islandIsSubIsland = exploreIsland(grid1, grid2, row, col, visited);
            if (islandIsSubIsland) numSubIslands++;
        }
    }

    return numSubIslands;
};

