// CONTRACT for catchFishInPool(grid, row, col, visited):
//     when this call returns, every water cell of the pool
//     containing (`row`, `col`) is in the visited set, and the
//     returned value is the total number of fish in that pool.
//     Land, out-of-bounds, and already-visited cells return 0.
const catchFishInPool = (grid, row, col, visited) => {
    // Base cases
    if (!isInBounds(grid, row, col)) return 0;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return 0;

    if (grid[row][col] === LAND) return 0;

    // Process node
    visited.add(curPositionString);

    // Unlike a plain area count, each cell contributes its fish count.
    let totalFishCaught = grid[row][col];

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor's side of
        // the pool is in the visited set and its fish are fully counted.
        // Trust it, do not trace it. This cell's own fish plus each
        // neighbor's guaranteed total add up to exactly this function's
        // contract: every fish in the pool, counted once.
        totalFishCaught += catchFishInPool(grid, newRow, newCol, visited);
    }

    return totalFishCaught;
};

const findMaxFish = (grid) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    let maxFishCaught = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = grid[row][col];
            if (terrainType === LAND) continue;

            // The recursive leap of faith: trust the contract. When this
            // call returns, fishCaught is every fish in this pool and all of
            // the pool's cells are in the visited set, so the loop can never
            // count this pool again. We do not trace inside; we just compare
            // it to the running maximum and move on.
            const fishCaught = catchFishInPool(grid, row, col, visited);
            maxFishCaught = Math.max(maxFishCaught, fishCaught);
        }
    }

    return maxFishCaught;
};

const FARMLAND = 1;

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for exploreGroup(land, row, col, visited, boundingBox):
//     when this call returns, every farmland cell of the group
//     containing (`row`, `col`) is in the visited set, and
//     `boundingBox` has been stretched to cover every one of
//     those cells.
const exploreGroup = (land, row, col, visited, boundingBox) => {
    // Base cases
    if (!isInBounds(land, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    if (land[row][col] !== FARMLAND) return;

    // Process node
    visited.add(curPositionString);

    // Grow the bounding box so it covers this cell. Since each group is a
    // perfect rectangle, the box's corners end up being the group's corners.
    boundingBox.minRow = Math.min(boundingBox.minRow, row);
    boundingBox.minCol = Math.min(boundingBox.minCol, col);
    boundingBox.maxRow = Math.max(boundingBox.maxRow, row);
    boundingBox.maxCol = Math.max(boundingBox.maxCol, col);

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor's side of
        // the group is in the visited set and the box covers it. Trust
        // it, do not trace it. This function already put (`row`, `col`)
        // into visited and stretched the box over it, and each
        // neighbor's contract covers the rest — together, that is this
        // function's full contract, kept.
        exploreGroup(land, newRow, newCol, visited, boundingBox);
    }
};

const findFarmland = (land) => {
    const numRows = land.length;
    const numCols = land[0].length;

    const allGroups = [];
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);

            if (visited.has(curPositionString)) continue;

            const terrainType = land[row][col];
            if (terrainType !== FARMLAND) continue;

            // Start the box as just this cell; the DFS stretches it out.
            const boundingBox = {
                minRow: row,
                minCol: col,
                maxRow: row,
                maxCol: col,
            };

            // The recursive leap of faith: trust the contract. When this
            // call returns, the whole group is in the visited set and
            // boundingBox holds its exact corners. We do not trace inside;
            // we just read the corners off the box and record them.
            exploreGroup(land, row, col, visited, boundingBox);

            allGroups.push([
                boundingBox.minRow,
                boundingBox.minCol,
                boundingBox.maxRow,
                boundingBox.maxCol,
            ]);
        }
    }

    return allGroups;
};
